        standardized.push((features[5] - 2.1826124509e+00) / 1.0277086234e-01);
        standardized.push((features[6] - 2.4018702416e+01) / 7.3439169358e+00);
        standardized.push((features[7] - 3.9387237959e+04) / 4.4362324953e+03);
